 bodyAnatomy.show(selected.type,bodyView()||internal&&!focus);bodyAnatomy.isolate(selected.type,bodyView()&&$('#organOnly').checked);organs.visible=internal&&!focus;heart.visible=(isCardiac(selected)&&focus&&!generalHeart()&&!internalHeart())||(internal&&!focus&&!organAssets.heartInternal);labels.forEach(l=>{l.visible=focus&&isCardiac(selected)&&!generalHeart()&&!internalHeart()&&(!fetalThreeVT()||['Ao','PA','SVC','기관'].includes(l.userData.label));l.position.copy(l.userData.originalPosition);if(fetalThreeVT()&&l.userData.label==='Ao')l.position.set(-.07,.52,.02);if(fetalThreeVT()&&l.userData.label==='PA')l.position.set(.29,.49,.06);});
